package managers

import androidx.compose.runtime.Composable

interface IBillingManager {

    fun startConnection()

    fun getAllProductDetails(finishLoad: (List<ProductDetails>) -> Unit)

    fun getPurchaseDetails(
        callback: (List<PurchaseResult>) -> Unit, subsType: Boolean = true
    )

    fun getPurchaseHistory(
        callback: (List<PurchaseHistory>) -> Unit, subsType: Boolean = true
    )

    fun getSubscribePrice(productId: String?): ProductInfo?

    fun getProductId(purchases: List<PurchaseResult>): String?

    fun usedFreeTrial(history: List<PurchaseHistory>): Boolean

    @Composable
    fun StripeByCardScreen(
        productId: String,
        onPurchase: (String, String?) -> Unit,
        onError: (String) -> Unit
    )

    @Composable
    fun StripeByAppleGoogleScreen(
        productId: String,
        onPurchase: (String, String?) -> Unit,
        onError: (String) -> Unit
    )
}

data class PurchaseResult(
    val purchaseState: PurchaseState,
    val isAcknowledged: Boolean,
    val products: List<String>,
    val purchaseToken: String,
    val orderId: String?,
    val originalJson: String,
)

data class PurchaseHistory(
    val products: List<String>,
    val purchaseToken: String,
    val originalJson: String,
)

data class PurchaseInfo(
    val productId: String
)

data class ProductInfo(
    val productId: String,
    val priceAmountMicros: Long,
    val priceCurrencyCode: String
)

data class ProductDetails(
    val productDetails: PurchaseInfo,
    val discountDetails: PurchaseInfo?
)

enum class PurchaseState {
    PURCHASED, PENDING, UNSPECIFIED_STATE
}