package ui.screens.onboarding.compatibilityAnswers

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.error_message_google_error_text
import fiori.sharedmodule.generated.resources.onboarding_compatibility_finish_text
import dependencies.di
import dependencies.RepositoriesProvider
import kotpref.DelayedActionExecutor
import kotpref.models.AppVariant
import kotpref.models.EDialogType
import kotpref.models.account.AccountFilter
import kotpref.models.profile.CompatibilityAnswerStatus
import kotpref.models.profile.CompatibilityQuestion
import ui.components.EventVM
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotpref.eventBus.CancelUserCompatibility
import kotpref.eventBus.EventBusManager
import kotpref.eventBus.UpdateUserCompatibility
import kotpref.models.account.Account
import kotpref.models.typeConverter.DateTimeConverter
import org.kodein.di.instance
import ui.resources.ResManager


sealed class OnBoardingCompatibilityAnswersEvent : EventVM {
    data object Back : OnBoardingCompatibilityAnswersEvent()
    data object OnBoardingFinish : OnBoardingCompatibilityAnswersEvent()
    data class LoadPeopleSuccess(val peopleList: MutableList<Account>) :
        OnBoardingCompatibilityAnswersEvent()
}

class OnboardingCompatibilityAnswersComposeVM(
    val language: String,
    private val viewModelCallback: (OnBoardingCompatibilityAnswersEvent) -> Unit
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val dialogManager = repositoriesProvider.dialogManager
    private val userRegistered = accountRepository.getAppKeys().userRegistered
    var currentQuestion = 0
    var questions = mutableListOf<CompatibilityQuestion>()
    val answers = hashMapOf<Int, CompatibilityAnswerStatus>()
    var questionState = mutableStateOf(QuestionState.DEFAULT)
    var startAnimation = false
    var lastTimeAnimationFinish = 0L

    val isLoading = mutableStateOf(true)

    init {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val filter = accountRepository.getMyFilter()
            questions = filter?.questions ?: mutableListOf()
            if (questions.isEmpty()) {
                accountRepository.loadQuestions(onSuccess = {
                    questions = it
                    isLoading.value = false
                })
            } else isLoading.value = false
        }
    }

    fun getCurrentQuestion() =
        if (questions.isEmpty()) {
            skipCompatibility()
            CompatibilityQuestion()
        } else questions[currentQuestion]


    fun getPreviousQuestion() = questions[currentQuestion - 1]
    fun getNextQuestion() = questions[currentQuestion + 1]

    var chooseAnswer = false
    private var finishAnswered = false
    private var acceptCancelQuestionnaire = false

    fun showChooseCompatibility() {
        chooseAnswer = false
        val currentPos = currentQuestion + 1
        val questionsSize = questions.size
        if (currentPos >= questionsSize) {
            if (finishAnswered) return
            isLoading.value = true
            finishAnswered = true
            accountRepository.updateUserCompatibility(answers, {
                DelayedActionExecutor({ isLoading.value = false }, 300)
                if (userRegistered) {
                    viewModelScope.launch(Dispatchers.Main) {
                        EventBusManager.post(UpdateUserCompatibility())
                        //router.route(Destination.Back())
                        viewModelCallback(OnBoardingCompatibilityAnswersEvent.Back)
                        val dialogText =
                            ResManager.getString(Res.string.onboarding_compatibility_finish_text)
                        dialogManager.showMessageDialog(dialogText)
                    }
                } else {
                    if (AppVariant.isElizium()) {
                        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
                            val filter = accountRepository.getMyFilter() ?: AccountFilter()
                            filter.filters.withQuestionnaire = true
                            accountRepository.saveAccountFilter(filter)
                            viewModelCallback(
                                OnBoardingCompatibilityAnswersEvent.LoadPeopleSuccess(
                                    mutableListOf()
                                )
                            )
                        }
                    }
                    accountRepository.getAppKeys().onboardingCompatibilityAnswers = true
                    //router.route(Destination.OnBoardingFinish())
                    viewModelCallback(OnBoardingCompatibilityAnswersEvent.OnBoardingFinish)
                }
            }, onError = {
                viewModelScope.launch(Dispatchers.Main) {
                    finishAnswered = false
                    dialogManager.showMessageDialog(ResManager.getString(Res.string.error_message_google_error_text))
                    isLoading.value = false
                }
            })
        } else {
            if (questionState.value == QuestionState.NEXT_QUESTION) {
                questionState.value = QuestionState.DEFAULT
                viewModelScope.launch {
                    delay(200)
                    questionState.value = QuestionState.NEXT_QUESTION
                }
            } else questionState.value = QuestionState.NEXT_QUESTION
        }
    }

    fun finishAnimation() {
        startAnimation = false
        lastTimeAnimationFinish = DateTimeConverter.currentTimeMillis()
    }

    private var skipCompatibility = false

    fun skipCompatibility() {
        if (userRegistered) {
            skipCompatibility = true
            //router.route(Destination.Back())
            viewModelCallback(OnBoardingCompatibilityAnswersEvent.Back)
            EventBusManager.post(UpdateUserCompatibility())
        } else {
            //router.route(Destination.OnBoardingFinish())
            viewModelCallback(OnBoardingCompatibilityAnswersEvent.OnBoardingFinish)
        }
    }

    private var lastClick = 0L

    @UiThread
    fun back() {
        if (currentQuestion != 0) {
            val currentTime = DateTimeConverter.currentTimeMillis()
            if (currentTime - lastClick < 200) return
            lastClick = currentTime
        }
        onBackClick()
    }

    private var previousQuestionButtonPressed = false
    private fun onBackClick() {
        if (previousQuestionButtonPressed ||
            startAnimation || DateTimeConverter.currentTimeMillis() - lastTimeAnimationFinish < 100
        ) return

        if (currentQuestion == 0) {
            //router.route(Destination.Back())
            viewModelCallback(OnBoardingCompatibilityAnswersEvent.Back)
        } else {
            currentQuestion--
            if (questionState.value == QuestionState.PREVIOUS_QUESTION) {
                questionState.value = QuestionState.DEFAULT
                viewModelScope.launch {
                    delay(200)
                    questionState.value = QuestionState.PREVIOUS_QUESTION
                }
            } else questionState.value = QuestionState.PREVIOUS_QUESTION
        }
    }

    @UiThread
    fun backSystem() {
        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastClick < 200) return
        lastClick = currentTime

        fun showDialogAndClosePage() {
            dialogManager.showMessageDialog(
                EDialogType.DIALOG_ACCOUNT_CANCEL_COMPATIBILITY,
                callback = {
                    EventBusManager.post(CancelUserCompatibility())
                    acceptCancelQuestionnaire = true
                    //router.route(Destination.Back())
                    viewModelCallback(OnBoardingCompatibilityAnswersEvent.Back)
                },
                onCancel = { skipCompatibility = false })
        }

        return if (skipCompatibility && acceptCancelQuestionnaire) onBackClick()
        else if (skipCompatibility) {
            showDialogAndClosePage()
        } else if (finishAnswered) onBackClick()
        else if (currentQuestion != 0) {
            onBackClick()
        } else if (acceptCancelQuestionnaire || !userRegistered) onBackClick()
        else {
            showDialogAndClosePage()
        }
    }
}

enum class QuestionState {
    PREVIOUS_QUESTION, DEFAULT, NEXT_QUESTION
}