var isMobileLayout = false
var isMobileDevice = false
var resultWidth = 0.0

@Composable
fun <T : androidx.lifecycle.ViewModel> rememberJsViewModel(
    key: Any? = null,
    factory: () -> T
): T {
    return remember(key) { factory() }
}


@Composable
fun getJsScreenSizeInfo(): ScreenSizeInfo {
    var width by remember { mutableStateOf(window.innerWidth) }
    var height by remember { mutableStateOf(window.innerHeight) }

    LaunchedEffect(Unit) {
        val resizeListener: (dynamic) -> Unit = {
            width = window.innerWidth
            height = window.innerHeight
        }
        window.addEventListener("resize", resizeListener)
    }
    val ratio = window.devicePixelRatio
    isMobileLayout = width <= 768 && ratio >= 2

    val hasTouch = window.navigator.maxTouchPoints as? Int ?: 0
    isMobileDevice = hasTouch > 0 && width <= 1024

    return remember(width, height) {
        ScreenSizeInfo(
            heightPx = height,
            widthPx = width,
            isMobileDevice = isMobileDevice,
            isMobileLayout = isMobileLayout
        )
    }
}

@Composable
fun stringResource(resource: StringResource): String = ActualAppStrings.get(resource.key)

@Composable
fun stringResource(resource: StringResource, arg: Any): String =
    formatString(stringResource(resource), arg)

@Composable
fun stringResource(resource: StringResource, arg1: Any, arg2: Any): String =
    formatString(stringResource(resource), arg1, arg2)

object ActualAppStrings {

    val currentAppLanguageCode = MutableStateFlow("en")

    internal fun formatString(format: String, vararg args: Any): String {
        var result = format
        args.forEachIndexed { index, arg ->
            result = result.replace("%${index + 1}\$s", arg.toString())
        }
        return result
    }

    @Composable
    fun get(key: String): String {
        val currentLang by currentAppLanguageCode.collectAsState()

        val langMap = remember(currentLang) {
            when (currentLang) {
                "ru" -> RuStringsMap
                "uk" -> UkStringsMap
                "es" -> EsStringsMap
                "pt" -> PtStringsMap
                "de" -> DeStringsMap
                "nl" -> NlStringsMap
                "it" -> ItStringsMap
                "sv" -> SvStringsMap
                "fr" -> FrStringsMap
                "ko" -> KoStringsMap
                "ja" -> JaStringsMap
                else -> EnStringsMap
            }
        }
        return langMap[key] ?: EnStringsMap[key] ?: ""
    }

    fun getString(key: String): String {
        val currentLang = currentAppLanguageCode.value

        val langMap = when (currentLang) {
            "ru" -> RuStringsMap
            "uk" -> UkStringsMap
            "es" -> EsStringsMap
            "pt" -> PtStringsMap
            "de" -> DeStringsMap
            "nl" -> NlStringsMap
            "it" -> ItStringsMap
            "sv" -> SvStringsMap
            "fr" -> FrStringsMap
            "ko" -> KoStringsMap
            "ja" -> JaStringsMap
            else -> EnStringsMap
        }
        return langMap[key] ?: EnStringsMap[key] ?: ""
    }
}