sealed class TabBars {
    object EmptyTabBar : TabBars()
    data class OnlyTitleTabBar(val title: String) : TabBars()
    data class DefaultTabBar(val title: String) : TabBars()
    data class TabBarWithRightButton(
        val leftButtonTitle: String = "",
        val tabBarTitle: String = "",
        val rightButtonTitle: String,
        val onRightButtonClick: (() -> Unit)
    ) : TabBars()
    data class TabBarWithRightIconButton(
        val tabBarTitle: String,
        val rightButtonIcon: Painter,
        val onRightButtonClick: (() -> Unit)
    ) : TabBars()
}


@Composable
fun OnlyTitleTabBar(title: String) {
    CustomTabBar({ }, tabBarType = TabBars.OnlyTitleTabBar(title))
}

@Composable
fun CustomTabBar(title: String, isSingleLine: Boolean = false, onBack: () -> Unit) {
    CustomTabBar(onBack, tabBarType = TabBars.DefaultTabBar(title), isSingleLine = isSingleLine)
}

@Composable
fun CustomTabBar(
    onBack: () -> Unit,
    alpha: Float = 1f,
    isColor: Boolean = true,
    withBackground: Boolean = true,
    isSingleLine: Boolean = false,
    tabBarType: TabBars
) {
    Column {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp)
                .background(if (withBackground) MainTheme.colors.main_color_header else Color.Transparent)
        ) {
            if (tabBarType !is TabBars.OnlyTitleTabBar) {
                if (tabBarType is TabBars.TabBarWithRightButton && tabBarType.leftButtonTitle.isNotEmpty()) {
                    TabBarTextButton(
                        title = tabBarType.leftButtonTitle,
                        alpha = 1f,
                        isColor = true,
                        onClick = onBack
                    )
                } else {
                    TabBarBackIcon(onBack = onBack)
                }
            }

            when (tabBarType) {
                is TabBars.TabBarWithRightButton -> {
                    if (tabBarType.tabBarTitle.isEmpty()) {
                        Box(modifier = Modifier.weight(1f))
                    } else {
                        TabBarTitle(
                            tabBarType,
                            Modifier
                                .align(Alignment.CenterVertically)
                                .weight(1f)
                        )
                    }
                    TabBarTextButton(
                        title = tabBarType.rightButtonTitle,
                        alpha = alpha,
                        isColor = isColor,
                        onClick = tabBarType.onRightButtonClick
                    )
                }

                is TabBars.DefaultTabBar, is TabBars.OnlyTitleTabBar ->
                    TabBarTitle(
                        tabBarType,
                        Modifier.align(Alignment.CenterVertically),
                        isSingleLine = isSingleLine
                    )

                is TabBars.TabBarWithRightIconButton -> {
                    TabBarTitle(
                        tabBarType,
                        Modifier
                            .align(Alignment.CenterVertically)
                            .weight(1f)
                    )
                    TabBarIcon(tabBarType.rightButtonIcon, tabBarType.onRightButtonClick)
                }

                else -> {}
            }
        }

        if (withBackground) DividerLine(background = MainTheme.colors.main_color_background)
    }
}

@Composable
fun TabBarWithCenterTitle(
    title: String,
    rightButtonTitle: String,
    isColor: Boolean = true,
    isSingleLine: Boolean = false,
    showBackButton: Boolean = true,
    alpha: Float = 1f,
    onBack: () -> Unit,
    rightButtonClick: () -> Unit = {}

) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(56.dp)
            .background(MainTheme.colors.main_color_header)
    ) {
        val titlePadding = remember { mutableStateOf(0) }
        TitleView(
            title,
            Modifier
                .align(Alignment.Center)
                .padding(start = titlePadding.value.pxToDp(), end = titlePadding.value.pxToDp()),
            isSingleLine
        )

        if (showBackButton) {
            TabBarBackIcon(
                Modifier
                    .align(Alignment.CenterStart)
                    .onSizeChanged {
                        if (rightButtonTitle.isEmpty()) titlePadding.value = it.width
                    }) { onBack() }
        }

        TabBarTextButton(
            modifier = Modifier
                .align(Alignment.CenterEnd)
                .onSizeChanged {
                    if (rightButtonTitle.isNotEmpty()) titlePadding.value = it.width
                    val width = it.width
                },
            title = rightButtonTitle,
            alpha = alpha,
            isColor = isColor,
            onClick = rightButtonClick
        )
    }
}


@Composable
fun TabBarTextButton(
    modifier: Modifier = Modifier,
    title: String,
    alpha: Float,
    isColor: Boolean,
    onClick: (() -> Unit)
) {
    Box(
        contentAlignment = Alignment.Center,
        modifier = modifier
            .fillMaxHeight()
            .clickable { onClick.invoke() }) {
        Text(
            title,
            color = if (isColor) MainTheme.colors.app_main_color.copy(alpha) else MainTheme.colors.text_color_blue_light,
            fontSize = 15.sp,
            fontWeight = if (isColor) FontWeight.Bold else FontWeight.Normal,
            modifier = Modifier.padding(horizontal = 16.dp)
        )
    }
}

@Composable
fun TabBarBackIcon(modifier: Modifier = Modifier, onBack: () -> Unit) {
    Image(
        painterResource(Res.drawable.ic_back_arrow),
        modifier = Modifier
            .fillMaxHeight()
            .padding(horizontal = 16.dp)
            .clickable { onBack.invoke() },
        contentDescription = null,
        colorFilter = ColorFilter.tint(MainTheme.colors.app_main_color)
    )
}

@Composable
fun TabBarIcon(icon: Painter, onClick: () -> Unit) {
    Image(
        icon,
        modifier = Modifier
            .fillMaxHeight()
            .padding(horizontal = 16.dp)
            .clickable { onClick.invoke() },
        contentDescription = null,
        colorFilter = ColorFilter.tint(MainTheme.colors.app_main_color)
    )
}

@Composable
fun TabBarTitle(
    tabBarTitle: TabBars,
    modifier: Modifier = Modifier,
    isSingleLine: Boolean = false
) {
    var startPadding: Dp = 8.dp

    val title: String = when (tabBarTitle) {
        is TabBars.TabBarWithRightButton -> tabBarTitle.tabBarTitle
        is TabBars.DefaultTabBar -> tabBarTitle.title
        is TabBars.OnlyTitleTabBar -> {
            startPadding = 16.dp
            tabBarTitle.title
        }

        else -> ""
    }
    TitleView(
        title = title,
        modifier = modifier.padding(start = startPadding, end = 16.dp),
        isSingleLine
    )
}

@Composable
private fun TitleView(title: String, modifier: Modifier, isSingleLine: Boolean = false) {
    AutoResizeText(
        modifier,
        title,
        color = MainTheme.colors.text_color_default,
        fontSizeRange = FontSizeRange(20.sp),
        fontWeight = FontWeight.Medium,
        maxLines = if (isSingleLine) 1 else Int.MAX_VALUE,
        rememberKey = title
    )
}

@Composable
fun PeopleTabBar(
    screenType: Int,
    swipeIsChecked: Boolean,
    title: String,
    filterSelected: MutableState<Boolean>,
    isCompatibilitySelect: MutableState<Boolean>,
    searchClick: () -> Unit,
    compatibilityClick: () -> Unit,
    filterClick: () -> Unit,
    changeScreen: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(56.dp)
            .background(MainTheme.colors.main_color_header)
    ) {
        if (screenType == 1) {
            Row(
                modifier = Modifier.fillMaxHeight(),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Spacer(modifier = Modifier.width(16.dp))
                PeopleTopBarSwitchButton(swipeIsChecked = swipeIsChecked) {
                    changeScreen.invoke()
                }

            }
        }

        TitleView(
            title = title,
            modifier = Modifier
                .padding(start = 16.dp, end = 16.dp)
                .align(if (screenType == 1) Alignment.Center else Alignment.CenterStart)
        )

        Row(
            modifier = Modifier
                .fillMaxHeight()
                .align(Alignment.CenterEnd)
                .padding(end = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .width(40.dp)
                    .padding(vertical = 8.dp)
                    .clickable { searchClick.invoke() },
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painterResource(Res.drawable.ic_people_search),
                    modifier = Modifier.size(24.dp),
                    contentDescription = null,
                    colorFilter = ColorFilter.tint(MainTheme.colors.app_main_color)
                )
            }
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .width(40.dp)
                    .padding(vertical = 8.dp)
                    .clickable { compatibilityClick.invoke() },
                contentAlignment = Alignment.Center
            ) {
                if (isCompatibilitySelect.value) {
                    Box(
                        modifier = Modifier
                            .size(34.dp)
                            .background(
                                color = MainTheme.colors.ic_people_search_tint,
                                shape = CircleShape
                            ),
                    )
                }

                Image(
                    painterResource(Res.drawable.ic_people_compatibility),
                    contentDescription = null,
                    modifier = Modifier.size(24.dp),
                    colorFilter = ColorFilter.tint(MainTheme.colors.app_main_color)
                )
            }
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .width(40.dp)
                    .padding(vertical = 8.dp)
                    .clickable { filterClick.invoke() },
                contentAlignment = Alignment.Center
            ) {
                if (filterSelected.value) {
                    Box(
                        modifier = Modifier
                            .size(34.dp)
                            .background(
                                color = MainTheme.colors.ic_people_search_tint,
                                shape = CircleShape
                            ),
                    )
                }

                Image(
                    painterResource(Res.drawable.ic_people_filter),
                    modifier = Modifier.size(24.dp),
                    contentDescription = null,
                    colorFilter = ColorFilter.tint(MainTheme.colors.app_main_color)
                )
            }
        }
        DividerLine(
            modifier = Modifier.align(Alignment.BottomCenter),
            background = MainTheme.colors.main_color_background
        )
    }
}

@Composable
fun PeopleTopBarSwitchButton(
    modifier: Modifier = Modifier,
    swipeIsChecked: Boolean = false,
    size: Dp = 36.dp,
    iconSize: Dp = 20.dp,
    padding: Dp = 2.dp,
    parentShape: Shape = CircleShape,
    toggleShape: Shape = CircleShape,
    animationSpec: AnimationSpec<Dp> = tween(durationMillis = 300),
    onClick: () -> Unit
) {
    val offset by animateDpAsState(
        targetValue = if (swipeIsChecked) 0.dp else size,
        animationSpec = animationSpec, label = ""
    )

    Box(
        modifier = modifier
        .width(size * 2)
        .height(size)
        .clip(shape = parentShape)
        .clickable { onClick.invoke() }
        .background(MainTheme.colors.top_bar_switch_background)
    ) {
        val brush = Brush.linearGradient(
            listOf(
                MainTheme.colors.gradient_main_button_start,
                MainTheme.colors.gradient_main_button_end
            )
        )
        Box(
            modifier = Modifier
                .size(size)
                .offset(x = offset)
                .padding(all = padding)
                .clip(shape = toggleShape)
                .background(brush = brush)
        )
        Row(
            modifier = Modifier.fillMaxSize()
        ) {
            Box(
                modifier = Modifier.size(size),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painterResource(Res.drawable.ic_top_bar_swipe_icon),
                    modifier = Modifier.size(iconSize),
                    contentDescription = null,
                    alpha = if (swipeIsChecked) 1f else 0.5f
                )
            }
            Box(
                modifier = Modifier.size(size),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painterResource(Res.drawable.ic_top_bar_people_icon),
                    modifier = Modifier.size(iconSize),
                    contentDescription = null,
                    alpha = if (swipeIsChecked) 0.5f else 1f
                )
            }
        }
    }
}