class WebSocketManager(
    val okHttpClient: HttpClient,
    val endpoint: Endpoint,
    val sessionAppKeys: IAppKeysStorage,
    val notificationsUtils: INotificationManager,
    val userAgent: String,
    val deviceName: String,
    val os: Int,
    val hasInternetConnection: () -> Boolean
) {

    private val WebSocketTAG = "WebSocket"

    private val sessionLogger = CommonLogger()
    private var appVersion = "1.0"
    private var lastOpening = 0L

    var webSocketSession: DefaultClientWebSocketSession? = null
    private var receiveJob: Job? = null
    var responseCallback: (String) -> Unit = {}

    private val messages = mutableListOf<String>()
    val coroutineExceptionHandler = CoroutineExceptionHandler { _, throwable ->
        throwable.printStackTrace()
    }

    val socketRequestsResponseManager =
        SocketRequestsResponseManager(sessionAppKeys, notificationsUtils, ::readMessages)

    fun connectWebSocket(appVersion: String = this.appVersion, firstConnect: Boolean = false) {
        this.appVersion = appVersion

        //val lastConnectTime = Date.currentTimeMillis()
        //if (lastConnectTime - 500 < lastOpening || ChatRequests.userBlockByVerification) return
        //lastOpening = lastConnectTime
        if (sessionAppKeys.userToken.isEmpty()) return

        val url = endpoint.socketUrl()
        if (firstConnect) sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, "socketUrl = $url")

        CoroutineScope(Dispatchers.Default + coroutineExceptionHandler).launch {
            try {
                connectSocket()
            } catch (e: Exception) {
                onException()
            }
        }
    }

    private var lastTimeTryConnected = 0L

    private suspend fun connectSocket() {
        if (isConnected()) return

        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastTimeTryConnected < 5000) return
        lastTimeTryConnected = currentTime

        val token = getToken()
        okHttpClient.wss(urlString = endpoint.socketUrl(), request = {
            header("Authorization", token)
        }) {
            webSocketSession = this
            sessionLogger.log(LogLvl.DEBUG, "WebSocket", "onConnected")

            ChatRequests.isClose = false
            ChatRequests.isCloseByInternetDisconnect = false
            resetValues()
            val retryJson = if (messages.size > 0) messages[0] else ""
            if (retryJson.isNotEmpty()) {
                val message = "${SocketEvent.RetrySendMessage.event}  $retryJson"
                sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, message)
                sendJsonWebSocket(retryJson)
            }
            createSession(appVersion)

            incoming.receiveAsFlow().collect {
                val message = it.data.decodeToString()
                if (message.isNotEmpty()) {
                    sessionLogger.log(
                        LogLvl.DEBUG, "WebSocket", "received  $message"
                    )
                    nextMessage()
                    CoroutineScope(Dispatchers.Main).launch { responseCallback(message) }
                    socketRequestsResponseManager.socketResponse(message)
                } else sessionLogger.log(LogLvl.DEBUG, "WebSocket", "received null")
            }
        }
    }

    fun isConnected(): Boolean {
        return webSocketSession?.isActive ?: false
    }

    private fun onException() {
        if (ChatRequests.chatSendNewMessages) {
            ChatRequests.chatSendNewMessages = false
            messagesFailedToSend()
        }
        messages.clear()

        if (ChatRequests.reconnectCounter == 0) {
            ChatRequests.isCloseByInternetDisconnect = true
            closeWebSocket(true)
        }
        tryReconnect()
    }

    fun tryReconnect() {
        val reconnectTime =
            if (ChatRequests.isClose) ChatRequests.reconnectMessageTime * 10 else ChatRequests.reconnectMessageTime
        DelayedActionExecutor({
            val hasInternet = hasInternetConnection()

            if (hasInternet) {
                if (AppVariant.appActive) {
                    sessionLogger.log(
                        LogLvl.DEBUG, WebSocketTAG,
                        "tryReconnect with hasInternet: $hasInternet;  isClose: ${ChatRequests.isClose}"
                    )
                    reconnectWebSocket(true)
                } else tryReconnect()
            } else tryReconnect()
        }, reconnectTime)
    }

    fun reconnectWebSocket(fromException: Boolean = false) {
        if (ChatRequests.hasException && !fromException) {
            ChatRequests.hasException = false
            return
        }
        ChatRequests.hasException = false
        val message = SocketEvent.ReconnectWebSocket.event
        try {
            if (!AppVariant.appActive) return
            sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, message)
            if (!ChatRequests.isClose && !ChatRequests.isCloseByInternetDisconnect) {
                CoroutineScope(Dispatchers.Default + coroutineExceptionHandler).launch { webSocketSession?.close() }
                //webSocketClient = null
            }
            lastOpening = 0
            connectWebSocket()
        } catch (e: Throwable) {
            sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, "$message exception: ${e.message}")
            connectWebSocket()
        }
    }

    fun closeWebSocket(byInternetDisconnect: Boolean) {
        try {
            resetValues()
            if (!ChatRequests.isClose && !ChatRequests.isCloseByInternetDisconnect) {
                CoroutineScope(Dispatchers.Default + coroutineExceptionHandler).launch {
                    webSocketSession?.incoming?.cancel()
                    webSocketSession?.cancel()
                    webSocketSession?.close()?.also {
                        sessionLogger.log(
                            LogLvl.DEBUG, WebSocketTAG, SocketEvent.CloseWebSocket.event
                        )
                    }
                }
                //webSocketClient = null
            }
            if (!byInternetDisconnect && !ChatRequests.hasException) ChatRequests.isClose = true
            messages.clear()
            sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, "call closeWebSocket")
        } catch (e: Throwable) {
            sessionLogger.log(
                LogLvl.ERROR, WebSocketTAG, "closeWebSocket error: ${e.message ?: ""}"
            )
        }
    }


    private fun createSession(appVersion: String) {
        if (appVersion.isEmpty()) return
        val event = SocketEvent.Session
        val socket = SocketSessionBody(
            event.event, SocketSession(appVersion, userAgent, deviceName, os), Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event.event)
    }

    fun webSocketSend(json: String?, event: String = "") {
        if (json == null) return
        val message = "$event  $json"
        sessionLogger.log(LogLvl.DEBUG, WebSocketTAG, message)
        if (messages.size == 0) {
            messages.add(json)
            sendJsonWebSocket(json)
        } else {
            messages.add(json)
        }
    }

    private fun nextMessage() {
        if (messages.size > 1) {
            messages.removeAt(0)
            val json = messages[0]
            sessionLogger.log(
                LogLvl.DEBUG, WebSocketTAG, "${SocketEvent.NextMessage.event}  $json"
            )
            sendJsonWebSocket(json)
        } else messages.clear()
    }

    private fun sendJsonWebSocket(json: String) {
        try {
            sendEvent(json)
        } catch (e: Throwable) {
            sessionLogger.log(
                LogLvl.ERROR, WebSocketTAG, "sendJsonWebSocket error: ${e.message ?: ""}"
            )
        }
    }

    private fun sendEvent(json: String) {
        CoroutineScope(Dispatchers.Default + coroutineExceptionHandler).launch {
            webSocketSession?.let { if (it.isActive) it.send(json) }
        }
    }

    private fun messagesFailedToSend() = try {
        messages.filter { it.contains("") }
        EventBusManager.post(FailedToSendMessages())
    } catch (e: Throwable) {

    }

    fun readMessages(chatId: Int, messages: MutableList<String>) {
        if (messages.size == 0) return
        val event = SocketEvent.ReadMessages.event
        val socket = SocketReadBody(
            event, SocketRead(chatId, messages), Endpoint.version
        )
        webSocketSend(JsonObjectConverter.objectToString(socket), event)
    }

    fun addChatRequestCallbacks(
        event: SocketEvent,
        onSuccess: (String?) -> Unit,
        onError: (String?) -> Unit
    ) {
        socketRequestsResponseManager.successCallbacks[event.getResponse()] = onSuccess
        socketRequestsResponseManager.errorCallbacks[event.getResponse()] = onError
    }


    private fun resetValues() {
        //resendMessageTime = 3000
        ChatRequests.reconnectMessageTime = 1000
        ChatRequests.reconnectCounter = 0
        ChatRequests.chatSendNewMessages = false
        ChatRequests.hasException = false
    }

    fun getToken(userToken: String = sessionAppKeys.userToken): String {
        return "Bearer $userToken"
    }
}