package kotpref.models.paywall

import kotlinx.serialization.SerialName

@kotlinx.serialization.Serializable
data class UserAdaptyPaywalls(

    @SerialName("adapty_settings_config") var adaptySettingsConfig: AdaptySettingsConfig? = null,
    @SerialName("adapty_paywall_config") var adaptyPaywallConfig: AdaptyPaywallConfig? = null,
    @SerialName("adapty_subscriptions_config") var adaptySubscriptionsConfig: AdaptySubscriptionsConfig? = null,
    @SerialName("discount") var adaptyDiscountConfig: AdaptyDiscountConfig? = null

)
