sealed class OnBoardingCompatibilityEvent : EventVM {
    data object Back : OnBoardingCompatibilityEvent()
    data object ProfileCompatibilityAnswers : OnBoardingCompatibilityEvent()
    data object OnBoardingNextPage : OnBoardingCompatibilityEvent()
    data object SkipCompatibility : OnBoardingCompatibilityEvent()
}

class OnboardingCompatibilityVM(
    private val viewModelCallback: (OnBoardingCompatibilityEvent) -> Unit,
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val amplitudeManager by di.instance<AmplitudeManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val dialogManager = repositoriesProvider.dialogManager
    private val userRegistered = accountRepository.getAppKeys().userRegistered

    val text = mutableStateOf("")
    val buttonText = mutableStateOf("")
    val backButtonVisibility = mutableStateOf(false)

    init {
        if (!userRegistered) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCompatibilityScreenShown)
        }

        accountRepository.getAppKeys().showShareProfileAfterRegistration = false
        backButtonVisibility.value = userRegistered

        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = accountRepository.getMyAccount()
            if (!myAccount?.info?.compatibilityAnswers.isNullOrEmpty()) {
                text.value = ResManager.getString(Res.string.onboarding_compatibility_reply_text)
                buttonText.value =
                    ResManager.getString(Res.string.onboarding_compatibility_reply_btn)
            } else {
                text.value = ResManager.getString(Res.string.onboarding_compatibility_text)
                buttonText.value = ResManager.getString(Res.string.onboarding_compatibility_btn)
            }
        }

        accountRepository.loadQuestions({})
    }

    fun startCompatibility() {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = accountRepository.getMyAccount()
            val lessThanOneDay =
                DateTimeConverter.lessThanDays(myAccount?.compatibilitiesUpdatedAt, 1, false)
            if (lessThanOneDay) {
                val message =
                    ResManager.getString(Res.string.error_message_account_edit_survey_text)
                dialogManager.showMessageDialog(message)
            } else {
                if (userRegistered) {
                    AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.compatibilityStart.name)
                    //router.route(Destination.ReplaceFragment(Destination.ProfileCompatibilityAnswers()))
                    viewModelCallback(OnBoardingCompatibilityEvent.ProfileCompatibilityAnswers)
                } else {
                    AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.onboardingCompatibilityStart.name)
                    amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCompatibilityScreenStartClicked)
                    //router.route(Destination.OnBoardingNextPage())
                    viewModelCallback(OnBoardingCompatibilityEvent.OnBoardingNextPage)
                }
            }
        }

    }

    fun skipCompatibility() {
        if (userRegistered) {
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.compatibilitySkip.name)
            back()
        } else {
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.onboardingCompatibilitySkip.name)
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCompatibilityScreenSkipClicked)
            //router.route(Destination.OnBoardingNextPage(2))
            viewModelCallback(OnBoardingCompatibilityEvent.SkipCompatibility)
        }
    }

    @UiThread
    fun back() {
        //router.route(Destination.Back())
        viewModelCallback(OnBoardingCompatibilityEvent.Back)
    }

    @UiThread
    fun backSystem() {
        if (userRegistered) {
            back()
        }
        /*when {
            accountRepository.getAppKeys().onboardingWithSubscription -> {
                accountRepository.getAppKeys().onboardingCurrentPage -= 2
            }
            accountRepository.settingsOnboardingType() != 2 -> {
                accountRepository.getAppKeys().onboardingCurrentPage -= 3
            }
            else -> {
                accountRepository.getAppKeys().onboardingCurrentPage--
            }
        }
        return false*/
    }
}