package web.views.alerts

import androidx.compose.runtime.Composable
import androidx.compose.runtime.snapshots.SnapshotStateList
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.btn_cancel
import fiori.sharedmodule.generated.resources.dialog_btn_ok
import fiori.sharedmodule.generated.resources.error_message_error_title
import fiori.sharedmodule.generated.resources.error_message_google_error_text
import managers.ShowAlertState
import org.jetbrains.compose.resources.StringResource
import web.helpers.stringResource

@Composable
fun JsShowAlertDialogs(showDialogState: SnapshotStateList<ShowAlertState>) {
    if (showDialogState.isNotEmpty()) {
        showDialogState.forEach {
            when (val state = it) {
                ShowAlertState.Hide -> {}
                is ShowAlertState.ShowDefaultDialog<*, *> -> {
                    val stateTitle = state.title
                    val stateMessage = state.message

                    val title: String = when (stateTitle) {
                        is String -> stateTitle
                        is StringResource -> stringResource(stateTitle)
                        else -> ""
                    }
                    val message: String = when (stateMessage) {
                        is String -> stateMessage
                        is StringResource -> stringResource(stateMessage)
                        else -> ""
                    }

                    JsDefaultAlert(title, message) { showDialogState.remove(it) }
                }

                is ShowAlertState.ShowOkCancelDialog -> {
                    val okText = state.okText.ifEmpty { stringResource(Res.string.dialog_btn_ok) }
                    val cancelText =
                        state.cancelText.ifEmpty { stringResource(Res.string.btn_cancel) }
                    JsDefaultAlert(
                        state.title, state.message, okText, cancelText,
                        dismissOnClickOutside = state.dismissOnClickOutside,
                        withCloseButton = state.withCloseButton,
                        onPositiveClick = { state.onOkClick() },
                        onNegativeClick = state.onCancelClick,
                        onDismiss = { showDialogState.remove(it) }
                    )
                }

                is ShowAlertState.ShowInputTextDialog -> {
                    JsDefaultAlert(
                        state.title, state.message, state.okText, state.cancelText,
                        dismissOnClickOutside = state.dismissOnClickOutside,
                        inputFieldPlaceholder = state.inputPlaceholder,
                        onPositiveClick = state.onOkClick,
                        onDismiss = { showDialogState.remove(it) }
                    )
                }

                is ShowAlertState.AlertByType -> {
                    JsAlertByType(
                        state.alertType,
                        dismissOnClickOutside = state.dismissOnClickOutside,
                        withCloseButton = state.withCloseButton,
                        onPositiveClick = { state.onOkClick() },
                        onNegativeClick = state.onCancelClick,
                        onDismiss = { showDialogState.remove(it) }
                    )
                }

                is ShowAlertState.ShowErrorMessage -> {
                    JsDefaultAlert(
                        stringResource(Res.string.error_message_error_title), state.message
                    ) { showDialogState.remove(it) }
                }

                is ShowAlertState.SomethingWrongError -> {
                    JsDefaultAlert(
                        stringResource(Res.string.error_message_error_title),
                        stringResource(Res.string.error_message_google_error_text)
                    ) { showDialogState.remove(it) }
                }
            }
        }
    }
}