data class ScreenSizeInfo(
    val heightPx: Int, val widthPx: Int,
    val isMobileDevice: Boolean = false, val isMobileLayout: Boolean = false
)

@JsName("hideLoader")
external fun hideLoader()

@Composable
@Page
fun Index() {
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(1)
        hideLoader()
    }

    val viewModel: AppScreenVM = rememberJsViewModel { AppScreenVM() }

    val screenSize = getJsScreenSizeInfo()
    val width = screenSize.widthPx
    val height = screenSize.heightPx
    val currentScreenAspectRation = width / height
    val minAspectRation = 10.88 / 16.0
    if (width > 0) {
        val logger = CommonLogger()
        logger.log(
            LogLvl.DEBUG, "App",
            "isMobileLayout = ${screenSize.isMobileLayout}, isMobileDevice = ${screenSize.isMobileDevice}"
        )
        logger.log(
            LogLvl.DEBUG, "App",
            "screenWidth = ${screenSize.widthPx}, screenHeight = ${screenSize.heightPx}"
        )
        logger.log(
            LogLvl.DEBUG, "App",
            "currentAspectRation = $currentScreenAspectRation, minAspectRation = $minAspectRation"
        )
    }

    val platInfoManager by di.instance<IPlatformInfoManager>()
    platInfoManager.hideStartLoader()
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(JsMainTheme.colors.main_color_background),
        contentAlignment = Alignment.BottomCenter
    ) {
        val customModifier = if (AppVariant.isWeb()) {
            val mod = if (currentScreenAspectRation > minAspectRation) {
                resultWidth =
                    (height / 16.0 * 9)//.unsafeCast<CSSLengthOrPercentageValue>()
                if (AppVariant.isDebug()) println("DEBUG: App resultWidth = $resultWidth")
                if (resultWidth < 350) resultWidth = 350.0
                Modifier.width(resultWidth.px)
            } else Modifier.fillMaxWidth()
            mod.fillMaxHeight().align(Alignment.BottomCenter)
        } else {
            Modifier.fillMaxSize()
        }

        Box(modifier = customModifier) {
            Box(modifier = Modifier.fillMaxSize()) {
                ScreenStates(viewModel)
            }
        }
    }
}

@Composable
private fun ScreenStates(viewModel: AppScreenVM) {
    val uiState by viewModel.getUiState().collectAsState()
    when (uiState) {
        AppNavigationPage.Loading -> Box(Modifier.fillMaxSize()) {
            JsImageView(
                Res.drawable.ic_logo_start_page,
                Modifier.fillMaxWidth(40.percent).align(Alignment.Center)
            )
        }

        AppNavigationPage.StartScreen -> StartPagesNavigation { viewModel.obtainEvent(it) }
        AppNavigationPage.OnboardingScreen -> OnboardingPagesNavigation(viewModel) {
            viewModel.obtainEvent(it)
        }

        AppNavigationPage.MainScreen -> DownloadAppScreen()
    }

    JsShowAlertDialogs(viewModel.showDialogState)
}