package kotpref.models.paywall

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotpref.models.AppVariant

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 27.03.2023.
 */
@Suppress("PLUGIN_IS_NOT_ENABLED")
@Serializable
data class AdaptySubscriptionsConfig(

    @SerialName("show_plus_subscriptions")
    val showPlusSubscriptions: Boolean? = null,

    @SerialName("open_unlim_subscriptions_from_settings")
    val openUnlimSubscriptionsFromSettings: Boolean? = null,

    @SerialName("open_unlim_subscriptions_when_limits_finish")
    val openUnlimSubscriptionsWhenLimitsFinish: Boolean? = null,

    var productIds: List<String>? = null,

    @SerialName("plus_popular_product_id")
    private var plusPopularProductId: String? = null,

    @SerialName("unlim_popular_product_id")
    private var unlimPopularProductId: String? = null,

    @SerialName("paywall_with_new_buttons_style")
    private var paywallWithBoxButtonsStyle: Boolean? = null,

    @SerialName("box_discount_plus_subscription")
    private var boxDiscountPlusSubscription: String? = null,

    @SerialName("box_discount_unlim_subscription")
    private var boxDiscountUnlimSubscription: String? = null,

    @SerialName("show_cancel_anytime")
    private var showCancelAnytime: Boolean? = null,

    @SerialName("show_bottom_total_price")
    private var showBottomTotalPrice: Boolean? = null,

    @SerialName("new_horizontal_button_style")
    private var newHorizontalButtonStyle: Boolean? = null,

    @SerialName("settings_for_apple_review")
    private var settingsForAppleReview: Boolean? = null,

    @SerialName("apple_review_for_build_version")
    private var appleReviewForBuildVersion: String? = null,

    @SerialName("custom_subs_for_build_version")
    private var customSubscriptionsForBuildVersion: String? = null,

    @SerialName("annual_12_months_text")
    private var annual12MonthsText: Boolean? = null,

    ) {

    fun getProductIdList(): List<String>? {
        if (getCustomSubscriptionsForBuildVersion()) {
            val subsBillings = mutableListOf(
                Billings.Plus12, Billings.Plus1, Billings.Plus6,
                Billings.BetaUnlim12Discount, Billings.Unlim1, Billings.Unlim6
            )
            return subsBillings.map { it.getSubscribe() }
        } else {
            return productIds
        }
    }

    fun isOpenUnlimSubscriptionsFromSettings(): Boolean? {
        return if (AppVariant.isTestBuild()) openUnlimSubscriptionsFromSettings else openUnlimSubscriptionsFromSettings
    }

    fun isOpenUnlimSubscriptionsWhenLimitsFinish(): Boolean? {
        return if (AppVariant.isTestBuild()) openUnlimSubscriptionsWhenLimitsFinish else openUnlimSubscriptionsWhenLimitsFinish
    }

    fun getPlusPopularProductId(): String? {
        return if (AppVariant.isTestBuild()) plusPopularProductId else plusPopularProductId
    }

    fun getUnlimPopularProductId(): String? {
        return if (AppVariant.isTestBuild()) unlimPopularProductId else unlimPopularProductId
    }

    fun getBoxDiscountPlusSubscription(): String? {
        return if (AppVariant.isTestBuild()) boxDiscountPlusSubscription else boxDiscountPlusSubscription
    }

    fun getBoxDiscountUnlimSubscription(): String? {
        return if (AppVariant.isTestBuild()) boxDiscountUnlimSubscription else boxDiscountUnlimSubscription
    }

    fun isShowCancelAnytime(): Boolean? {
        return if (AppVariant.isTestBuild()) false else showCancelAnytime
    }

    fun isShowBottomTotalPrice(): Boolean? {
        return if (AppVariant.isTestBuild()) showBottomTotalPrice else showBottomTotalPrice
    }

    fun getSettingsForAppleReview(): Boolean? {
        return if (getAppleReviewForBuildVersion()) true
        else if (AppVariant.isTestBuild()) settingsForAppleReview
        else settingsForAppleReview
    }

    fun getNewHorizontalButtonsStyle(): Boolean? {
        return if (AppVariant.isTestBuild()) newHorizontalButtonStyle else newHorizontalButtonStyle
    }

    fun getPaywallWithBoxButtonsStyle(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallWithBoxButtonsStyle else paywallWithBoxButtonsStyle
    }

    private fun getAppleReviewForBuildVersion(): Boolean {
        val appVersion = AppVariant.appVersion
        return if (AppVariant.isTestBuild()) appVersion == appleReviewForBuildVersion else appVersion == appleReviewForBuildVersion
    }

    private fun getCustomSubscriptionsForBuildVersion(): Boolean {
        val appVersion = AppVariant.appVersion
        return if (AppVariant.isTestBuild()) appVersion == customSubscriptionsForBuildVersion else appVersion == customSubscriptionsForBuildVersion
    }

    fun getAnnual12MonthsText(): Boolean? {
        return if (AppVariant.isTestBuild()) annual12MonthsText else annual12MonthsText
    }
}