package managers

import dependencies.RecaptchaInterop
import dependencies.WebContainer
import kotlinx.browser.document
import kotlinx.browser.localStorage
import kotlinx.browser.window
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.suspendCancellableCoroutine
import kotpref.models.SettingsEmulatorAttributes
import kotpref.utils.IPlatformInfoManager
import kotpref.utils.PlatformType
import org.w3c.dom.HTMLElement
import storage.AppKeysSecureDefault
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException

class PlatformInfoManager : IPlatformInfoManager {
    override fun getPlatformType(): PlatformType {
        return getOperatingSystem()
    }

    override fun getDeviceId(callback: (String) -> Unit) {
        val deviceId = getOrCreateDeviceId()
        callback(deviceId)
    }

    override fun getDeviceId(): String {
        return getOrCreateDeviceId()
    }

    override fun getUUIDString(): String {
        return FingerprintHelper.generateDeviceId()
    }

    override fun sendEmail(title: String, text: String) {

    }

    override fun isEmulator(settingsEmulatorAttributes: SettingsEmulatorAttributes?): Boolean {
        return false
    }

    override fun getAppVersion(): String {
        return "4.5.8"
    }

    override fun getLanguage(): String {
        return window.navigator.language
    }

    override fun hasInternetConnection(): Boolean {
        return true
    }

    override fun getCountryCode(): String {
        return "us"
    }

    override fun showReCaptcha(onSuccess: (String) -> Unit, onFailure: (String?) -> Unit) {
        val siteKey = AppKeysSecureDefault().verificationCaptchaKey
        CoroutineScope(Dispatchers.Main).launch {
            delay(50)
            val token = launchRecaptcha(siteKey)
            onSuccess(token)
        }
    }

    private suspend fun waitForRecaptchaToken(siteKey: String): String = suspendCancellableCoroutine { cont ->
        var called = false
        RecaptchaInterop.initRecaptchaCallback { token ->
            println("initRecaptchaCallback token = $token")
            if (!called) {
                called = true
                cont.resume(token)
                RecaptchaInterop.initRecaptchaCallback {}
            }
        }
        cont.invokeOnCancellation {
            RecaptchaInterop.initRecaptchaCallback {}
        }

        try {
            println("Calling setupRecaptcha for container: ${WebContainer.CaptchaScreen.screenName}")
            RecaptchaInterop.setupRecaptcha(WebContainer.CaptchaScreen.screenName, siteKey)
        } catch (e: dynamic) {
            if (cont.isActive) {
                cont.resumeWithException(RuntimeException("Failed to setup reCAPTCHA: ${e.message}"))
            }
        }
    }

    private suspend fun launchRecaptcha(siteKey: String): String {
        val token = waitForRecaptchaToken(siteKey)
        return token
    }

    override fun hideStartLoader() {
        val target = document.getElementById(WebContainer.StartLoader.screenName) as? HTMLElement
        target?.style?.display = "none"
    }

    override fun gpsEnabled(): Boolean {
        return true
    }

    override fun startGPSActivity() {

    }

    private fun getOrCreateDeviceId(): String {
        val key = "user_uuid"
        val existingId = localStorage.getItem(key)
        if (existingId != null) {
            return existingId
        }

        val newId = FingerprintHelper.generateDeviceId()
        localStorage.setItem(key, newId)
        return newId
    }

    private fun getOperatingSystem(): PlatformType {
        val userAgent = window.navigator.userAgent
        return when {
            userAgent.contains("Android", ignoreCase = true) -> PlatformType.WebAndroid
            userAgent.contains("iPhone", ignoreCase = true) ||
                    userAgent.contains("iPad", ignoreCase = true) -> PlatformType.WebIOS

            userAgent.contains("Macintosh", ignoreCase = true) -> PlatformType.WebMacBook
            userAgent.contains("Windows", ignoreCase = true) -> PlatformType.Web
            userAgent.contains("Linux", ignoreCase = true) -> PlatformType.Web
            else -> PlatformType.Web
        }
    }
}
