package web.views.datePicker.picker

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.background
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxWidth
import com.varabyte.kobweb.compose.ui.modifiers.height
import web.helpers.dp


@Composable
fun JsPickerScrollingDividers(selectorProperties: SelectorProperties, rowCount: Int) {
    if (selectorProperties.enabled().value) {
        val dividerSize = (rowCount - 1) / 2
        Column(Modifier.fillMaxSize()) {
            repeat(dividerSize) { Box(Modifier.weight(1f)) }

            Box(
                modifier = Modifier.fillMaxWidth().height(3.dp)
                    .background(selectorProperties.borderColor().value)
            )

            Box(Modifier.weight(1f))

            Box(
                modifier = Modifier.fillMaxWidth().height(3.dp)
                    .background(selectorProperties.borderColor().value)
            )

            repeat(dividerSize) { Box(Modifier.weight(1f)) }
        }
    }
}

